    /* ===================================================================
       THE PICK — one favour of three, on the motor's card.
       =================================================================== */
    function pool() {
      var out = [], i, P;
      for (i = 0; i < PERKS.length; i++) {
        P = PERKS[i];
        if (P.lv <= stage.perks && !has(P.id)) out.push(P);
      }
      return out;
    }
    function dealPick(n) {
      var src = pool(), out = [], i, tot, x, k;
      while (out.length < n && src.length) {
        tot = 0;
        for (i = 0; i < src.length; i++) tot += PICK_WEIGHT[src[i].r];
        x = Rand.range(0, tot);
        for (k = 0; k < src.length - 1; k++) { x -= PICK_WEIGHT[src[k].r]; if (x <= 0) break; }
        out.push(src[k].id); src.splice(k, 1);
      }
      return out;
    }
    /* `then` runs once the pick is closed — the next deal */
