      for (i = 0; fresh && i < fresh.length; i++) {
        if (has(fresh[i]) || deal3.indexOf(fresh[i]) >= 0) continue;
        if (deal3.length < 3) deal3.push(fresh[i]); else deal3[2 - i % 3] = fresh[i];
      }
      if (!deal3.length) { then(); return; }
