      var fresh = opt && opt.fresh && !ghost, act = P.act && !ghost;
      n.className = "bs-perk r-" + P.r + (ghost ? " ghost" : "") + (fresh ? " fresh" : "");
      n.style.setProperty("--c", F.col); n.style.setProperty("--r", R.col);
      n.innerHTML = '<span class="bs-pfam"></span><span class="bs-pico">' + (src ? '<img alt="" draggable="false" src="' + src + '">' : "") + '</span>' +
                    '<b class="bs-pname"></b><i class="bs-ptext"></i>' + (act ? '<span class="bs-pact"></span>' : "") +
                    '<span class="bs-prar"></span>' + (fresh ? '<span class="bs-pnew"></span>' : "");
      n.querySelector(".bs-pfam").textContent = upper(Lang.t(F.name));
      n.querySelector(".bs-pname").textContent = ghost ? "???" : upper(Lang.t(P.name));
      n.querySelector(".bs-ptext").textContent = ghost ? "" : Lang.t(P.text);
      if (act) n.querySelector(".bs-pact").textContent = upper(Lang.t("Used with a tap"));
      n.querySelector(".bs-prar").textContent = upper(Lang.t(R.name));
