      mc.className = "mt-card bs-pc";
      mc.innerHTML = '<p class="mt-eyebrow"></p><h2 class="mt-h wrap"></h2><div class="mt-body"></div>';
      mc.querySelector(".mt-eyebrow").textContent = upper(Lang.t("Rail full"));
